import * as E from './engine.js';
function col(key,label,opts={}){return {key,label,value:r=>r[key],...opts};}
const price=(key,label)=>col(key,label,{numeric:true,roundCopy:true,exportLabel:label+'(만원/평)',width:108});
const money=(key,label)=>col(key,label,{numeric:true,exportLabel:label+'(만 원)',width:108});
const base=[col('name','단지명',{width:140}),col('year','건축년도',{sort:r=>Number(r.year.split(',')[0])||Infinity}),col('dong','행정동',{exportLabel:'행정동(원본 동)'}),col('region','시군구'),col('address','주소',{width:80})];
const groupPeriod=[col('period','기간',{width:130}),col('group','집계 대상',{width:180})];
export const COLUMNS={periods:[...groupPeriod,col('typeText','타입',{width:76,sort:r=>r.type}),money('priceMinimum','최소 거래금액'),money('priceMaximum','최대 거래금액'),money('priceAverage','평균 거래금액'),price('minimum','최소평당가'),price('maximum','최대평당가'),price('average','평균평당가'),col('count','거래 건수',{numeric:true,value:r=>r.count||null})],volume:[...groupPeriod,col('count','거래 건수',{numeric:true,width:130})],apartments:[...base,col('pyeongText','면적(평형)',{sort:r=>r.areaMin,tie:r=>r.areaMax,width:110}),col('areaText','전용면적(㎡)',{sort:r=>r.areaMin,tie:r=>r.areaMax,width:120}),col('typeText','타입',{width:76,sort:r=>r.type}),price('minimum','최소평당가'),price('maximum','최대평당가'),price('average','평균평당가'),money('priceMinimum','최소 거래금액'),money('priceMaximum','최대 거래금액'),money('priceAverage','평균 거래금액'),col('count','거래 건수',{numeric:true})],districts:[base[2],base[3],base[0],base[1],price('average','평균평당가'),col('count','거래 건수',{numeric:true})],excluded:[col('rowNumber','원본 행',{numeric:true}),base[0],base[4],col('area','전용면적(㎡)',{value:r=>Number.isFinite(r.area)?E.areaText(r.area):'',sort:r=>r.area}),col('broker','중개사 소재지',{width:230}),col('reason','제외 사유',{width:160})],cases:[col('date','계약일',{value:r=>r.date||'날짜 미확인',sort:r=>r.date||'9999'}),base[0],col('pyeongText','평형',{value:r=>E.range(r.area/E.SQM_PER_PYEONG,r.area/E.SQM_PER_PYEONG,'평',2),sort:r=>r.area,width:90}),col('area','전용면적(㎡)',{value:r=>E.areaText(r.area),sort:r=>r.area}),col('type','타입',{value:r=>r.type+'타입',sort:r=>r.type}),col('floor','층',{sort:r=>E.number(r.floor)}),money('price','거래금액'),price('unitPrice','평당가')]};

export function rentalColumns(lease=''){
 const unit=(key,label)=>price(key,label);
 const converted=[unit('minimum','최소 환산 전세 평당가'),unit('maximum','최대 환산 전세 평당가'),unit('average','평균 환산 전세 평당가')].map(c=>({...c,width:166}));
 const counts=[col('count','거래 건수',{numeric:true}),col('missingRateCount','환산 불가 건수',{numeric:true,width:116})];
 const averages=[money('depositAverage','평균 보증금'),money('rentAverage','평균 월세')];
 const amounts=lease==='전세'?[unit('minimum','최소 전세 평당가'),unit('maximum','최대 전세 평당가'),unit('average','평균 전세 평당가')].map(c=>({...c,width:136})).concat([money('priceMinimum','최소 전세금'),money('priceMaximum','최대 전세금'),money('priceAverage','평균 전세금'),counts[0]]):lease==='월세'?[...averages,...converted,...counts]:[...converted,col('jeonseCount','전세 건수',{numeric:true}),col('monthlyCount','월세 건수',{numeric:true}),...counts];
 const details=[col('lease','전세·월세'),col('contract','신규·갱신'),money('deposit','보증금'),money('rent','월세'),col('rate','적용 전환율',{value:r=>r.rate==null?'':Number(r.rate.toFixed(4))+'%',sort:r=>r.rate??Infinity,width:110}),col('rateRegion','전환율 적용 지역',{width:150}),col('rateMonth','통계 기준월',{width:110}),col('rateStatus','적용 상태',{width:126}),money('price','환산 전세금'),{...price('unitPrice','환산 전세 평당가'),width:150}];
 return {periods:COLUMNS.periods.map(c=>['priceMinimum','priceMaximum','priceAverage'].includes(c.key)?{...c,label:c.label.replace('거래금액','환산 전세금'),width:166}:['minimum','maximum','average'].includes(c.key)?{...c,label:c.label.replace('평당가',' 환산 전세 평당가'),width:175}:c),volume:COLUMNS.volume,apartments:[...COLUMNS.apartments.slice(0,8),...amounts],districts:[...COLUMNS.districts.slice(0,4),col('address','주소',{width:80}),...(lease==='월세'?averages:[]),{...price('average',lease==='전세'?'평균 전세 평당가':'평균 환산 전세 평당가'),width:166},...counts],excluded:[...COLUMNS.excluded.slice(0,4),col('lease','전세·월세'),col('contract','신규·갱신'),money('deposit','보증금'),money('rent','월세'),col('reason','제외 사유',{width:160})],cases:[...COLUMNS.cases.slice(0,6),...details]};
}
